contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 vBase, uint128 vNft, uint16 feeRate, uint256 tokenId, uint256 ethValue)
        public
        payable
    {
        require(vNft > 0);
        require(feeRate <= 5000);
        require(address(this).balance >= ethValue);

        c.initialize(address(0), address(this), vBase, vNft, 0, feeRate, bytes32(0), false, false);

        bytes32 merkleRoot;
        merkleRoot = c.merkleRoot();

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = tokenId;
        uint256[] memory tokenWeights = new uint256[](1);

        if (merkleRoot == bytes32(0)) {
            tokenWeights[0] = vNft;
        } else {
            tokenWeights[0] = vNft;
            return;
        }

        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        proof.flags = new bool[](0);

        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        (netInputAmount, feeAmount, protocolFeeAmount) = c.buyQuote(vNft);

        uint256 totalSent = 0;
        bool reverted;
        try c.buy{value: ethValue}(tokenIds, tokenWeights, proof) returns (
            uint256 n,
            uint256 f,
            uint256 p
        ) {
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
            totalSent = ethValue;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (uint256 postNet, uint256 postFee, uint256 postProtocol) = c.buyQuote(0);
            assert(c.virtualBaseTokenReserves() >= vBase);
        } else {
            assert(true);
        }
    }

    receive() external payable {}

    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4) {
        return this.onERC721Received.selector;
    }
}

