contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        require(address(this).balance >= baseTokenAmount, "insufficient balance");

        address baseToken = c.baseToken();
        address nft = c.nft();

        uint256 beforeBaseBalance;
        uint256 beforeNftBalance;
        uint256 beforeAccountedNftCount;

        if (baseToken == address(0)) {
            beforeBaseBalance = address(c).balance;
        } else {
            beforeBaseBalance = ERC20(baseToken).balanceOf(address(c));
        }

        beforeNftBalance = ERC721(nft).balanceOf(address(c));

        c.deposit{value: baseToken == address(0) ? baseTokenAmount : 0}(tokenIds, baseTokenAmount);

        uint256 afterBaseBalance;
        uint256 afterNftBalance;

        if (baseToken == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(baseToken).balanceOf(address(c));
        }

        afterNftBalance = ERC721(nft).balanceOf(address(c));

        assert(afterNftBalance == beforeNftBalance + tokenIds.length);
        assert(afterBaseBalance == beforeBaseBalance + baseTokenAmount);
    }

    receive() external payable {}
